    exp(g_RT[11] - g_RT[18] + g_RT[3] - g_RT[4] + g_RT_qss[4]);
  amrex::Real x16 = -g_RT[10] + g_RT[9];
  amrex::Real x17 = g_RT[15] - g_RT_qss[4];
  amrex::Real x21 = g_RT[1] - g_RT[5];
  amrex::Real x25 = g_RT[3] - g_RT[6];
